from flask import redirect, url_for, request, make_response, render_template
from helpers.utils import escape_for_html

def init(app):

	@app.route('/benchmark/review/endpoint', methods=['GET'])
	def endpoint_get():
		return endpoint_post()

	@app.route('/benchmark/review/endpoint', methods=['POST'])
	def endpoint_post():
		RESPONSE = ""

		parts = request.path.split("/")
		param = parts[1]
		if not param:
			param = ""

		num = 86

		if 7 * 42 - num > 200:
			bar = 'This_should_always_happen'
		else:
			bar = param

		import platform
		import subprocess
		import helpers.utils

		argStr = ""
		if platform.system() == "Windows":
			argStr = "cmd.exe /c "
		else:
			argStr = "sh -c "
		argStr += f"echo {bar}"

		try:
			proc = subprocess.run(argStr, shell=True, capture_output=True, encoding="utf-8")

			RESPONSE += (
				helpers.utils.commandOutput(proc)
			)
		except IOError:
			RESPONSE += (
				"Problem executing command - subprocess.run(list) Test Case"
			)

		return RESPONSE
